/* ═══════════════════════════════════════════════════════════════════════════
   DETERMINISM
   ═══════════════════════════════════════════════════════════════════════════ */

function mulberry32(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const rand = mulberry32(20260908)

function ri(min: number, max: number): number {
  return Math.floor(rand() * (max - min + 1)) + min
}

function rf(min: number, max: number, dp = 2): number {
  return Number((rand() * (max - min) + min).toFixed(dp))
}

function pick<T>(list: readonly T[]): T {
  return list[Math.floor(rand() * list.length)] as T
}

/** Stable synthetic id — readable in the console, and unique per kind. */
let idCounter = 0
function id(prefix: string): string {
  idCounter += 1
  return `${prefix}-${String(idCounter).padStart(4, '0')}`
}

/* ═══════════════════════════════════════════════════════════════════════════
   DATES
   ═══════════════════════════════════════════════════════════════════════════ */

const NOW = new Date()

function iso(d: Date): string {
  return d.toISOString()
}

function isoDate(d: Date): string {
  return d.toISOString().slice(0, 10)
}

function addDays(d: Date, days: number): Date {
  const out = new Date(d)
  out.setDate(out.getDate() + days)
  return out
}

function minutesAgo(n: number): string {
  return iso(new Date(NOW.getTime() - n * 60_000))
}

function hoursAgo(n: number): string {
  return iso(new Date(NOW.getTime() - n * 3_600_000))
}

function daysAgo(n: number): string {
  return iso(addDays(NOW, -n))
}

function startOfWeek(d: Date): Date {
  const out = new Date(d)
  const day = out.getDay()
  out.setDate(out.getDate() + (day === 0 ? -6 : 1 - day))
  out.setHours(0, 0, 0, 0)
  return out
}

function lastSunday(d: Date): Date {
  const out = new Date(d)
  out.setDate(out.getDate() - (out.getDay() === 0 ? 7 : out.getDay()))
  out.setHours(6, 0, 0, 0)
  return out
}

function monthKey(back: number): string {
  const out = new Date(NOW.getFullYear(), NOW.getMonth() - back, 1)
  return `${out.getFullYear()}-${String(out.getMonth() + 1).padStart(2, '0')}`
}

function monthLabel(key: string): string {
  const [y, m] = key.split('-').map(Number)
  return new Date(y as number, (m as number) - 1, 1).toLocaleDateString('en-GB', {
    month: 'long',
    year: 'numeric',
  })
}

function daysInMonth(key: string): number {
  const [y, m] = key.split('-').map(Number)
  return new Date(y as number, m as number, 0).getDate()
}

const THIS_WEEK = startOfWeek(NOW)
const LAST_BUILD = lastSunday(NOW)
const MONTHS = [monthKey(3), monthKey(2), monthKey(1)]
const REPORTED_MONTH = MONTHS[2] as string

