const keywords: Keyword[] = SEED_KEYWORDS.map((k) => ({
  id: id('kw'),
  term: k.term,
  category: k.category,
  weight: k.weight,
  active: true,
  created_at: daysAgo(60),
}))

const KEYWORD_BY_TERM = new Map(keywords.map((k) => [k.term, k]))

/**
 * The five that trend, in rank order. Fixed rather than random so the
 * narrative across screens (theater → intelligence → calendar) is coherent.
 */
const TRENDING_TERMS = [
  'agentic AI',
  'reward modeling',
  'reinforcement learning',
  'RLHF',
  'post-training',
]

const TREND_REASONS: Record<string, string> = {
  'agentic AI':
    'Highest engagement velocity in the set: 41 posts this week carrying 68% more engagement than its four-run average.',
  'reward modeling':
    '3rd highest volume this week (34 posts) and the fastest-growing: engagement is up 52% against its four-run average.',
  'reinforcement learning':
    'The largest absolute volume (47 posts) with engagement steady within 4% of its four-run average — a reliable base, not a spike.',
  RLHF: 'Volume is flat but engagement per post rose 31%, concentrated in posts about annotator disagreement.',
  'post-training':
    'Smallest of the five by volume (22 posts) but the highest engagement per post at 214 — a narrow, highly engaged audience.',
}

/** Four historical runs plus the current one, so growth % is meaningful. */
const keywordSignals: KeywordSignal[] = []
for (const [runIndex, back] of [12, 9, 6, 3, 0].entries()) {
  const isCurrent = back === 0
  const capturedAt = daysAgo(back)
  const runId = id('run')

  const scored = keywords.map((k) => {
    const trendIndex = TRENDING_TERMS.indexOf(k.term)
    const trending = trendIndex >= 0
    const growth = trending ? rf(18, 68, 1) : rf(-22, 16, 1)
    const posts = trending ? ri(22, 47) : ri(3, 21)
    const engagement = posts * ri(64, 240)
    const base = Math.round((k.weight * 0.4 + (trending ? 44 : 12) + runIndex * 1.4) * rf(0.94, 1.06))
    return {
      keyword: k,
      trending,
      trendIndex,
      posts,
      engagement,
      growth,
      score: Math.max(9, Math.min(98, base)),
    }
  })

  const ranked = [...scored].sort((a, b) => {
    if (a.trending !== b.trending) return a.trending ? -1 : 1
    if (a.trending && b.trending) return a.trendIndex - b.trendIndex
    return b.score - a.score
  })

  for (const [i, s] of ranked.entries()) {
    keywordSignals.push({
      id: id('sig'),
      keyword_id: s.keyword.id,
      term: s.keyword.term,
      run_id: runId,
      post_count: s.posts,
      total_engagement: s.engagement,
      avg_engagement: (s.engagement / Math.max(1, s.posts)).toFixed(2),
      velocity: rf(2.4, 28.6).toFixed(2),
      growth_pct: s.growth.toFixed(2),
      trend_score: s.score,
      rank: i + 1,
      is_trending: isCurrent ? s.trending : s.trending && rand() > 0.25,
      trend_reason: s.trending ? (TREND_REASONS[s.keyword.term] ?? null) : null,
      captured_at: capturedAt,
    })
  }
}

/** The current run's signals — what every screen shows by default. */
const latestRunId = keywordSignals[keywordSignals.length - 1]?.run_id ?? null

