const VERDICT_REASONS: Record<string, (t: string) => string> = {
  validated: (t) => `Relevance ${t} against the brand topic set, from a High-credibility author with a research headline — above the 70 accept threshold.`,
  needs_review: (t) => `Relevance scored ${t}, between the 40 reject and 70 accept thresholds. Credibility is Medium, so the verdict is yours.`,
  duplicate: (t) => `Dice similarity ${t} against an item captured four days ago. Linked to the original rather than dropped.`,
  rejected: (t) => `Relevance ${t}, below the 40 reject threshold: the body is a hiring post that mentions the keyword once.`,
}

const scraped: ScrapedItem[] = []
for (let i = 0; i < 42; i += 1) {
  const body = POST_BODIES[i % POST_BODIES.length] as (typeof POST_BODIES)[number]
  const author = pick(AUTHORS)
  const source = pick(sources.slice(0, 3))
  const keyword = KEYWORD_BY_TERM.get(body.topic) ?? (keywords[0] as Keyword)

  // Deliberate verdict spread so all four buckets are populated on first load.
  const verdict =
    i % 9 === 4 ? 'needs_review' : i % 11 === 7 ? 'duplicate' : i % 13 === 9 ? 'rejected' : 'validated'
  const relevance =
    verdict === 'validated' ? ri(72, 97) : verdict === 'needs_review' ? ri(48, 69) : verdict === 'duplicate' ? ri(60, 88) : ri(18, 38)

  const reactions = ri(40, 1_480)
  const comments = ri(3, 140)
  const reposts = ri(1, 190)

  scraped.push({
    id: id('item'),
    keyword_id: keyword.id,
    keyword_term: keyword.term,
    run_id: latestRunId,
    external_id: `urn:li:activity:${7_100_000_000_000 + i * 977}`,
    title: body.title,
    snippet: body.snippet,
    url: `https://www.linkedin.com/feed/update/urn:li:activity:${7_100_000_000_000 + i * 977}/`,
    source_name: source.name,
    source_type: source.source_type,
    author_name: author.name,
    author_headline: author.headline,
    author_followers: author.followers,
    hashtags: body.tags,
    engagement: reactions + comments * 3 + reposts * 5,
    reactions,
    comments,
    reposts,
    relevance,
    credibility: relevance >= 74 ? 'High' : relevance >= 46 ? 'Medium' : 'Low',
    freshness: ri(38, 99),
    is_duplicate: verdict === 'duplicate',
    duplicate_of_id: null,
    duplicate_of_tag: null,
    validation: verdict as ScrapedItem['validation'],
    verdict_reason: (VERDICT_REASONS[verdict] as (t: string) => string)(
      verdict === 'duplicate' ? '0.74' : String(relevance),
    ),
    capture_source: 'fixture',
    posted_at: hoursAgo(ri(2, 320)),
    scraped_at: minutesAgo(ri(2, 240)),
  } as ScrapedItem)
}

// Link every duplicate to a real original — nothing is ever orphaned.
const firstValidated = scraped.find((s) => s.validation === 'validated')
for (const item of scraped) {
  if (item.validation === 'duplicate' && firstValidated) item.duplicate_of_id = firstValidated.id
}

