    const verdict = keywordIndex === 1 && i === 4 ? 'needs_review' : keywordIndex === 3 && i === 3 ? 'needs_review' : 'validated'
    const postCount = ri(6, 41) + (5 - i) * 3
    const engagement = postCount * ri(96, 260)
