function captionFor(seed: IdeaSeed): string {
  const tags = [seed.hashtag, 'AIResearch', 'Ethara'].slice(0, 3)
  return [
    seed.title + '.',
    '',
    seed.description,
    '',
    `The practical consequence: ${seed.angle.toLowerCase()}. We treat this as an engineering decision with an owner, not a research opinion.`,
    '',
    `At Ethara we build the environments and reward infrastructure this depends on.`,
    '',
    tags.map((t) => `#${t}`).join(' '),
  ].join('\n')
}

const ideas: Idea[] = []
const drafts: Record<string, Draft> = {}
const media: Record<string, MediaAsset> = {}

for (const [i, seed] of IDEA_SEEDS.entries()) {
  const ideaId = id('idea')
  const scheduled = addDays(THIS_WEEK, seed.dayOffset + (i >= 10 ? 7 : 0))
  const priority = Math.round(0.45 * seed.confidence + 0.35 * seed.brandRelevance + 0.2 * seed.trendScore)
  const hashtag = hashtags.find((h) => h.display_tag === seed.hashtag)
  const item = scraped.find((s) => s.keyword_term === seed.sourceTopic)

  ideas.push({
    id: ideaId,
    source_item_id: item?.id ?? null,
    hashtag_id: hashtag?.id ?? null,
    hashtag_display: seed.hashtag,
    title: seed.title,
    description: seed.description,
    source_topic: seed.sourceTopic,
    platform: seed.platform,
    alt_platforms:
      seed.platform === 'linkedin'
        ? [{ platform: 'facebook', score: ri(62, 80) }, { platform: 'x', score: ri(58, 78) }, { platform: 'instagram', score: ri(44, 68) }]
        : [{ platform: 'linkedin', score: ri(70, 92) }],
    scheduled_date: isoDate(scheduled),
    scheduled_time: seed.time,
    confidence: seed.confidence,
    priority_score: priority,
    platform_rank: null,
    calendar_slot: 'suggestion',
    status: seed.status,
    analysis: {
      format: seed.format,
      angle: seed.angle,
      audience: seed.audience,
      brandRelevance: seed.brandRelevance,
      trendScore: seed.trendScore,
      engagementLevel: seed.trendScore >= 88 ? 'High' : seed.trendScore >= 80 ? 'Medium' : 'Steady',
      bestDay: scheduled.toLocaleDateString('en-GB', { weekday: 'long' }),
      platformScore: ri(72, 96),
      slotReasons: SLOT_REASONS[seed.time] ?? (SLOT_REASONS.default as string[]),
    },
    feedback: [],
    is_new_trend: seed.isNewTrend,
    marketing_approved_by: seed.status === 'pending_leadership' || seed.status === 'approved' ? 'Ridhima' : null,
    marketing_approved_at: seed.status === 'pending_leadership' || seed.status === 'approved' ? hoursAgo(ri(3, 30)) : null,
    leadership_decision:
      seed.status === 'approved'
        ? { decision: 'approved', by: 'Arjun Mehta', at: hoursAgo(ri(1, 12)), published: false }
        : null,
    created_at: daysAgo(ri(1, 6)),
    updated_at: hoursAgo(ri(1, 40)),
  })

  // The first six ideas ship with a draft and a locally rendered creative, so
  // the calendar, review panel and previews all have real content on load.
  if (i < 8) {
    const body = captionFor(seed)
    drafts[`${ideaId}|${seed.platform}`] = {
      body,
      revision: i === 0 ? 3 : 1,
      model: 'ethara-writer',
      source: 'fixture',
      updatedAt: hoursAgo(ri(1, 20)),
    }
    media[`${ideaId}|${seed.platform}`] = renderBrandSvg({
      platform: seed.platform,
      headline: seed.title,
      kicker: seed.sourceTopic,
      concept: seed.format,
    })
  }
}

/**
 * The top-10 rule, applied exactly as `calendar.rank.select` applies it:
 * per platform independently, ranked by priority score.
 */
for (const platform of ['linkedin', 'instagram', 'x', 'facebook'] as Platform[]) {
  const forPlatform = ideas
    .filter((idea) => idea.platform === platform)
    .sort((a, b) => b.priority_score - a.priority_score)
  for (const [rank, idea] of forPlatform.entries()) {
    idea.platform_rank = rank + 1
    idea.calendar_slot = rank < 10 ? 'primary' : 'suggestion'
    idea.calendarSlot = idea.calendar_slot
    idea.platformRank = idea.platform_rank
    idea.draft = drafts[`${idea.id}|${idea.platform}`] ?? null
    idea.media = media[`${idea.id}|${idea.platform}`] ?? null
  }
}

